/**
 * Utility for counting the number of ways to make a target sum with unlimited copies of each coin.
 */
public final class CoinChange {

    private CoinChange() {
        // Utility class.
    }

    /**
     * Counts the number of unique combinations that sum to {@code sum}.
     * Duplicate coin denominations are ignored.
     */
    public static int count(int[] coins, int sum) {
        validateSum(sum);
        int[] normalizedCoins = normalizeCoins(coins);
        return Math.toIntExact(countCombinations(normalizedCoins, sum));
    }

    /**
     * Convenience overload for callers that already have coins as varargs.
     */
    public static int countWays(int sum, int... coins) {
        return count(coins, sum);
    }

    public static void main(String[] args) {
        CoinChangeCli.main(args);
    }

    private static void validateSum(int sum) {
        if (sum < 0) {
            throw new IllegalArgumentException("sum must be non-negative");
        }
    }

    private static int[] normalizeCoins(int[] coins) {
        if (coins == null) {
            throw new IllegalArgumentException("coins must not be null");
        }
        if (coins.length == 0) {
            return coins;
        }

        int[] normalized = coins.clone();
        java.util.Arrays.sort(normalized);

        int uniqueCount = 0;
        int previous = 0;
        for (int coin : normalized) {
            if (coin <= 0) {
                throw new IllegalArgumentException("coin values must be positive");
            }
            if (uniqueCount == 0 || coin != previous) {
                normalized[uniqueCount++] = coin;
                previous = coin;
            }
        }

        int[] uniqueCoins = new int[uniqueCount];
        System.arraycopy(normalized, 0, uniqueCoins, 0, uniqueCount);
        return uniqueCoins;
    }

    private static long countCombinations(int[] coins, int sum) {
        long[] ways = new long[sum + 1];
        ways[0] = 1L;

        for (int coin : coins) {
            for (int current = coin; current <= sum; current++) {
                ways[current] += ways[current - coin];
            }
        }

        return ways[sum];
    }
}

/**
 * Command-line entry point for the coin change utility.
 */
public final class CoinChangeCli {

    private CoinChangeCli() {
        // Utility class.
    }

    public static void main(String[] args) {
        try {
            run(args);
        } catch (IllegalArgumentException ex) {
            System.err.println(ex.getMessage());
            printUsage();
            System.exit(1);
        }
    }

    private static void run(String[] args) {
        if (args.length < 1) {
            throw new IllegalArgumentException("expected at least a sum");
        }

        int sum = parseNonNegativeInt(args[0], "sum");
        int[] coins = new int[args.length - 1];
        for (int i = 1; i < args.length; i++) {
            coins[i - 1] = parsePositiveInt(args[i], "coin");
        }

        System.out.println(CoinChange.countWays(sum, coins));
    }

    private static int parseNonNegativeInt(String value, String label) {
        try {
            int parsed = Integer.parseInt(value);
            if (parsed < 0) {
                throw new IllegalArgumentException(label + " must be non-negative");
            }
            return parsed;
        } catch (NumberFormatException ex) {
            throw new IllegalArgumentException("invalid " + label + ": " + value, ex);
        }
    }

    private static int parsePositiveInt(String value, String label) {
        int parsed = parseNonNegativeInt(value, label);
        if (parsed == 0) {
            throw new IllegalArgumentException(label + " values must be positive");
        }
        return parsed;
    }

    private static void printUsage() {
        System.err.println("Usage: java CoinChange <sum> [coin1 coin2 ...]");
        System.err.println("Example: java CoinChange 5 1 2 3");
        System.err.println("Example: java CoinChange 0");
    }
}

public final class CoinChangeTest {

    private CoinChangeTest() {
        // Test utility.
    }

    public static void main(String[] args) {
        assertCount(5, new int[] {1, 2, 3}, 5);
        assertCount(1, new int[] {1, 2, 3}, 0);
        assertCount(5, new int[] {2, 5, 3, 6}, 10);
        assertCount(2, new int[] {1, 1, 2}, 3);
        assertCount(1, new int[] {2, 2}, 4);
        assertCount(1, new int[] {}, 0);
        assertCount(0, new int[] {}, 5);
        assertThrows(() -> CoinChange.count(null, 5));
        assertThrows(() -> CoinChange.count(new int[] {1, 0}, 5));
        assertThrows(() -> CoinChange.count(new int[] {1, 2}, -1));

        System.out.println("All CoinChange tests passed.");
    }

    private static void assertCount(int expected, int[] coins, int sum) {
        int actual = CoinChange.count(coins, sum);
        if (actual != expected) {
            throw new AssertionError(
                "expected " + expected + " ways for sum " + sum + ", got " + actual
            );
        }
    }

    private static void assertThrows(Runnable action) {
        try {
            action.run();
        } catch (IllegalArgumentException expected) {
            return;
        }

        throw new AssertionError("expected IllegalArgumentException");
    }
}
